import { readFileSync } from 'node:fs';
const src = readFileSync(process.argv[2], 'utf8');
function el(tag) {
  const e = { tag, children: [], listeners: {}, value: '', disabled: false, type: '', textContent: '',
    append(...n) { for (const x of n) e.children.push(typeof x === 'string' ? { text: x } : x); },
    replaceChildren(...n) { e.children = []; e.append(...n); },
    addEventListener(t, f) { e.listeners[t] = f; } };
  return e;
}
const ids = {};
for (const id of ['booking-form','room','title','date','start','end','book','filter-date','show-all','booking-list','error']) ids[id] = el(id);
const calls = [];
let store = [{ id: 1, room: 'Aurora', title: '<b>x</b>', date: '2026-11-03', start: '09:00', end: '10:00' }];
const fetch = async (url, opts) => {
  calls.push([url, opts]);
  if (url === '/api/rooms') return { status: 200, json: async () => ({ rooms: ['A', 'B'] }) };
  if (url.startsWith('/api/bookings/')) return { status: 404, json: async () => ({ error: 'booking not found' }) };
  if (opts && opts.method === 'POST') return { status: 409, json: async () => ({ error: 'room is already booked from 09:00 to 10:00' }) };
