ids['booking-list'].children[0].children[1].listeners.click();
await tick(); await tick(); await tick();
console.log('after cancel', ids.error.textContent, calls.at(-1)[0]);
ids['filter-date'].value = '2026-11-03 x';
ids['filter-date'].listeners.change({});
await tick();
console.log(calls.at(-1)[0]);
store = [];
ids['show-all'].listeners.click();
await tick(); await tick();
